SELECT p.gender, p.age, d.name, s.name AS symptom, COUNT(DISTINCT a.deathtime)::FLOAT / NULLIF(COUNT(DISTINCT a.admittime), 0) AS mortality_rate, SUM(CASE WHEN d.name IN ('heart attack', 'stroke') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.admittime), 0) AS major_complication_rate, percentile_cont(0.75) within GROUP (ORDER BY (p.age + CASE WHEN d.name IN ('heart attack', 'stroke') THEN 1 ELSE 0 END)) AS survivor_los_percentile FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays s ON a.subject_id = s.subject_id WHERE p.gender = 'M' AND p.age BETWEEN 46 AND 56 AND d.name = 'acute myocardial infarction' GROUP BY p.gender, p.age, d.name, s.name ORDER BY p.gender, p.age, d.name, s.name NULLS LAST;